    result = []
    i, j = len(a) - 1, len(b) - 1

    while i >= 0 or j >= 0 or carry:
        curr_sum = carry
        if i >= 0:
            curr_sum += int(a[i])
            i -= 1
        if j >= 0:
            curr_sum += int(b[j])
            j -= 1
        result.append(str(curr_sum % 2))
        carry = curr_sum // 2

    return ''.join(reversed(result))

