def calculate(s):
    def tokenize(expr):
        tokens = []
        i = 0
        while i < len(expr):
            if expr[i].isspace():
                i += 1
            elif expr[i].isdigit():
                j = i
                while j < len(expr) and expr[j].isdigit():
                    j += 1
                tokens.append(int(expr[i:j]))
                i = j
            else:
                tokens.append(expr[i])
                i += 1
        return tokens

    def precedence(op):
        if op in ['+', '-']:
            return 1
        elif op in ['*', '/']:
            return 2
        return 0

    def shunting_yard(tokens):
        output = []
        operator_stack = []
        for token in tokens:
            if isinstance(token, int):
                output.append(token)
            elif token == '(':
                operator_stack.append(token)
            elif token == ')':
                while operator_stack and operator_stack[-1] != '(':
                    output.append(operator_stack.pop())
                operator_stack.pop()  # Remove '('
            else:  # operator
                while (operator_stack and 
                       operator_stack[-1] != '(' and 
                       precedence(operator_stack[-1]) >= precedence(token)):
                    output.append(operator_stack.pop())
                operator_stack.append(token)
        while operator_stack:
            output.append(operator_stack.pop())
        return output

    def evaluate_postfix(postfix):
        stack = []
        for token in postfix:
            if isinstance(token, int):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(int(a / b))  # truncate toward zero
        return stack[0]

    tokens = tokenize(s)
    postfix = shunting_yard(tokens)
    return evaluate_postfix(postfix)

def constructArray(n, k):
    result = []
    left, right = 1, n

    # Special case: if k == 1, return consecutive numbers
    if k == 1:
        return list(range(1, n + 1))

    # For k > 1, use zigzag pattern for first k+1 elements
    for i in range(k + 1):
        if i % 2 == 0:
            result.append(left)
            left += 1
        else:
            result.append(right)
            right -= 1

    # Append remaining numbers in ascending order
    while left <= right:
        result.append(left)
        left += 1

    return result

