from collections import defaultdict

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px == py:
            return
        if self.rank[px] < self.rank[py]:
            px, py = py, px
        self.parent[py] = px
        if self.rank[px] == self.rank[py]:
            self.rank[px] += 1

def canTraverseAllPairs(nums):
    n = len(nums)
    if n == 1:
        return True

    # Check if there's a duplicate value that is not 1
    # If all values are 1, then no traversal is possible except for same index
    # But since we need to traverse between different indices, if all nums[i] == 1,
    # then gcd(1,1) = 1, so no traversal possible between any distinct indices.
    if all(x == 1 for x in nums):
        return False

    uf = UnionFind(n)

    # Map each prime factor to the list of indices it appears in
    prime_to_indices = defaultdict(list)

    # Factorize each number and group indices by their prime factors
    for i, num in enumerate(nums):
        temp = num
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                prime_to_indices[d].append(i)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            prime_to_indices[temp].append(i)

    # For each prime factor, union all indices that have this factor
    for prime, indices in prime_to_indices.items():
        for j in range(1, len(indices)):
            uf.union(indices[0], indices[j])

    # Check if all indices are in the same component
    root = uf.find(0)
    for i in range(1, n):
        if uf.find(i) != root:
            return False

    return True

def getXORSum(arr1, arr2):
    result = 0
    for bit in range(32):
        cnt1 = sum(1 for x in arr1 if (x >> bit) & 1)
        cnt2 = sum(1 for x in arr2 if (x >> bit) & 1)
        if (cnt1 * cnt2) % 2 == 1:
            result |= (1 << bit)
    return result

